"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1495],{41495:a=>{a.exports=JSON.parse('{"slug":"inflyaciya-uskorilas-ohlazhdenie-ekonomiki","locale":"ru","title":"Недельная инфляция в России ускорилась вторую неделю подряд, а ожидания людей выросли до 14,2%","description":"Недельная инфляция ускорилась с 0,02% до 0,12% за три недели, ожидания людей выросли до 14,2%. Почему это важно для ставки Банка России 23 октября.","blocks":[{"id":"b001","kind":"paragraph","text":"За неделю 22–28 сентября 2026 года цены в России выросли на 0,12%. Неделей раньше рост был 0,06%, двумя неделями раньше 0,02%. Это самый быстрый недельный рост с конца июля. Если бы цены росли по 0,12% каждую неделю, за год вышло бы около 6,4% (1,0012 в 52-й степени), а цель Банка России 4%. Одна неделя мало что доказывает, но три подряд с ускорением уже заметны."},{"id":"b002","kind":"paragraph","text":"Овощи осенью дешевеют и тянут цены вниз, но всё медленнее: за последнюю неделю сентября картофель подешевел на 3,2%, неделей раньше на 3,4%. Одновременно яйца подорожали на 1,9%, гречка и пшено на 0,8%. Годовая инфляция на 28 сентября около 6,25%, а с начала года цены выросли на 4,93% против 4,29% за тот же период 2025 года."},{"id":"b003","kind":"paragraph","text":"Банк России в сентябре оценил устойчивую инфляцию в августе, то есть рост цен без случайных скачков, в 5–6% в пересчёте на год. Летом цены подскочили во многом из-за топлива: в июле рост с поправкой на сезон был 11,7% в пересчёте на год, в августе 6,9%. Скачок прошёл, но до цели 4% инфляция не опустилась, и ключевая ставка остаётся высокой, 14%."},{"id":"b004","kind":"paragraph","text":"Высокая ставка охлаждает экономику: кредиты дорогие, люди и компании меньше тратят, и цены растут медленнее. Но работает это лучше, когда люди верят в замедление цен. В сентябре они ждали, что цены за год вырастут на 14,2%, в августе ждали 13,7%, хотя на деле годовая инфляция около 6,25%. Для того, кто ждёт роста цен на 14%, ставка 14% почти ничего не стоит: купить сейчас кажется выгоднее, чем копить. Это называют инфляционными ожиданиями, и Банк России предупреждает, что высокие ожидания могут мешать замедлению инфляции."},{"id":"b005","kind":"paragraph","text":"Чего пока не знаем: это начало разгона или случайный всплеск. Официальные данные за сентябрь Росстат опубликует 9 октября, решение по ставке Банк России примет 23 октября. Для обычного человека расклад такой. Вклады пока обгоняют рост цен: средняя максимальная ставка в 10 крупнейших банках в конце сентября 13,05% против инфляции около 6,25%. Брать кредит в расчёте на скорое снижение ставки рискованно, а ждать снижения бесконечно тоже стоит денег: цены всё это время растут."},{"id":"b006","kind":"heading","text":"Какая инфляция в России в конце сентября 2026 года?"},{"id":"b007","kind":"paragraph","text":"На 28 сентября годовая инфляция около 6,25%, с начала года цены выросли на 4,93%. За последнюю неделю сентября цены выросли на 0,12%, это самый быстрый недельный рост с конца июля. Официальные данные за месяц Росстат опубликует 9 октября."},{"id":"b008","kind":"heading","text":"Почему инфляция ускорилась в сентябре 2026 года?"},{"id":"b009","kind":"paragraph","text":"Овощи по сезону дешевеют, но медленнее, чем неделей раньше. Одновременно дорожают яйца и крупы: яйца за последнюю неделю сентября подорожали на 1,9%. Банк России оценивает устойчивую инфляцию в 5–6% в пересчёте на год, выше цели 4%."},{"id":"b010","kind":"heading","text":"Что такое инфляционные ожидания и почему они важны для ставки?"},{"id":"b011","kind":"paragraph","text":"Это рост цен, которого люди ждут на год вперёд, в сентябре 2026 года 14,2%. Если человек ждёт такого роста, ставка 14% для него почти ничего не стоит, и он не откладывает покупки. Поэтому высокие ожидания мешают Банку России снижать ставку."}],"sources":[{"label":"Недельная инфляция за прошедшую неделю составила 0,12%","url":"https://www.vedomosti.ru/economics/news/2026/09/30/1233212-nedelnaya-inflyatsiya"},{"label":"Инфляция в России ускорилась до 0,06% за неделю","url":"https://www.vedomosti.ru/economics/news/2026/09/23/1231274-inflyatsiya-rossii-uskorilas"},{"label":"Инфляция в РФ с 22 по 28 сентября составила 0,12%, годовая замедлилась до 6,25%","url":"https://www.interfax.ru/business/1119451"},{"label":"Инфляционные ожидания россиян в сентябре выросли до 14,2%","url":"https://www.vedomosti.ru/economics/news/2026/09/22/1230887-inflyatsionnie-ozhidaniya"},{"label":"ЦБР оценил устойчивую инфляцию в августе в диапазоне 5–6%","url":"https://ru.themoscowtimes.com/2026/09/16/tsbr-otsenil-ustoychivuyu-inflyatsiyu-v-avguste-v-diapazone-5-6-a206280"},{"label":"Средняя максимальная ставка по вкладам десяти банков выросла до 13,05%","url":"https://ria.ru/20261001/bank-2121443529.html"},{"label":"Банк России сохранил ключевую ставку на уровне 14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"a98c31881322940d45b158db2ab6716a039490f89eea6f0ffe309fb1f7594ee1"}')}}]);